<script lang="ts">
  import { onMount } from 'svelte';
  import { invoke } from '@tauri-apps/api/core';
  import UiIcon from './UiIcon.svelte';
  let { username }: { username: string } = $props();
  type Target = { id:string;name:string;game_version:string;loader:string;version_id:string;pack_id:string|null };
  type Preset = {id:string;name:string;explanation:string;changes:Record<string,string>};
  type Workspace = {game_version:string;loader:string;options_exist:boolean;backup_available:boolean;manual_changes:boolean;current:Record<string,string>;presets:Preset[];mods:number;recommended_ram_gb:number;total_ram_gb:number|null;available_ram_gb:number|null;logical_threads:number;note:string};
  type Finding = {code:string;title:string;explanation:string;action:string};
  type Diagnosis = {findings:Finding[];inspected:number;source:string;note:string};
  type Sample = {fps:number;frame_time_ms:number|null;heap_used_mb:number;heap_max_mb:number;elapsed_seconds:number;focused:boolean;has_world:boolean};
  type FpsReport = {sample:Sample|null;samples:number;findings:Finding[];note:string};
  let targets=$state<Target[]>([]), selected=$state(''), workspace=$state<Workspace|null>(null), diagnosis=$state<Diagnosis|null>(null), report=$state<FpsReport|null>(null);
  let busy=$state(''), message=$state(''), failed=$state(false), confirmation=$state<Preset|'restore'|null>(null), watching=$state(false);
  let dialog=$state<HTMLDialogElement>();
  $effect(()=>{if(confirmation&&dialog&&!dialog.open)dialog.showModal();});
  let current=$derived(targets.find(target=>target.id===selected));
  let request=0;
  function args(){if(!current)throw new Error('Selecciona una instalación.');return {username,versionId:current.version_id,packId:current.pack_id};}
  async function perform(key:string, action:()=>Promise<void>){if(busy)return;busy=key;message='';failed=false;try{await action();}catch(error){message=String(error);failed=true;}finally{busy='';}}
  async function loadTargets(){await perform('targets',async()=>{targets=await invoke<Target[]>('studio_install_targets',{username});if(!targets.some(target=>target.id===selected))selected=targets[0]?.id??'';});await load();}
  async function load(){const id=++request;workspace=null;diagnosis=null;report=null;confirmation=null;if(!current)return;await perform('workspace',async()=>{const next=await invoke<Workspace>('performance_workspace',args());if(id===request)workspace=next;});}
  async function apply(){const next=confirmation;if(!next||!current)return;confirmation=null;await perform('apply',async()=>{workspace=await invoke<Workspace>(next==='restore'?'performance_restore':'performance_apply_preset',{...args(),...(next==='restore'?{}:{preset:next.id})});message=next==='restore'?'Configuración original restaurada y verificada.':'Perfil aplicado. Se conserva la copia original para deshacer.';});}
  async function inspect(){await perform('diagnose',async()=>{diagnosis=await invoke<Diagnosis>('performance_diagnose',args());});}
  async function sample(){if(watching||!current)return;const id=request;watching=true;try{const value=await invoke<FpsReport>('performance_samples',args());if(id===request)report=value;}catch(error){if(id===request){message=String(error);failed=true;}}finally{watching=false;}}
  onMount(()=>{void loadTargets();const timer=setInterval(()=>{if(!document.hidden&&current)void sample();},5000);return()=>{clearInterval(timer);request++;};});
</script>

<section class="performance-center">
  <header><div><span class="eyebrow">TP LABS · HERRAMIENTAS LOCALES</span><h2><UiIcon name="gauge" size={25}/>Centro de rendimiento</h2><p>Ajustes reversibles, métricas reales y diagnóstico de tu instalación.</p></div><button disabled={!!busy} onclick={() => void loadTargets()}><UiIcon name="refresh" size={15}/>Actualizar</button></header>
  <label class="target">Instalación o modpack<select bind:value={selected} disabled={!!busy} onchange={() => void load()}>{#each targets as target}<option value={target.id}>{target.name} · {target.game_version} · {target.loader}</option>{/each}</select></label>
  {#if !targets.length&&!busy}<p class="notice">Primero instala una versión desde Jugar o Instalaciones. Este panel solo modifica instancias existentes.</p>{/if}
  {#if busy}<p role="status" class="notice">Procesando…</p>{/if}
  {#if message}<p role={failed?'alert':'status'} class:error={failed} class="notice">{message}</p>{/if}
  {#if workspace}
    <div class="hardware"><article><UiIcon name="memory"/><small>RAM sugerida</small><strong>{workspace.recommended_ram_gb} GB</strong><span>No se cambia automáticamente</span></article><article><UiIcon name="chip"/><small>Memoria del equipo</small><strong>{workspace.total_ram_gb??'—'} GB</strong><span>{workspace.available_ram_gb??'—'} GB disponibles ahora</span></article><article><UiIcon name="archive"/><small>Instancia</small><strong>{workspace.mods} mods</strong><span>{workspace.logical_threads} hilos lógicos detectados</span></article></div>
    <p class="note">{workspace.note}</p>
    <section class="group"><div class="section-heading"><div><h3>Perfil gráfico por instancia</h3><p>Revisa cada cambio antes de aplicarlo. Minecraft debe estar cerrado.</p></div><button disabled={!!busy||!workspace.backup_available||workspace.manual_changes} onclick={() => confirmation='restore'}><UiIcon name="rewind" size={15}/>Restaurar original</button></div>
      {#if workspace.manual_changes}<p class="notice">Detectamos cambios manuales posteriores. TP conserva tus preferencias y bloquea la sobrescritura. La copia original permanece en config/tp-performance/options.before.</p>{/if}
      <div class="presets">{#each workspace.presets as preset}<article><h4>{preset.name}</h4><p>{preset.explanation}</p><button disabled={!!busy||workspace.manual_changes} onclick={() => confirmation=preset}><UiIcon name="sliders" size={15}/>Revisar cambios</button></article>{:else}<p>No hay presets gráficos validados para esta versión. Se conservan sus opciones originales; la orientación de memoria y el diagnóstico siguen disponibles.</p>{/each}</div>
      <details><summary>Opciones actuales</summary><dl>{#each Object.entries(workspace.current) as [key,value]}<div><dt>{key}</dt><dd>{value}</dd></div>{/each}</dl></details>
      <small>Los shaders se mantienen como estaban. No se instala ningún mod, no se alteran flags JVM y no se garantizan más FPS.</small>
    </section>
    <section class="group"><div class="section-heading"><div><h3><UiIcon name="monitor" size={19}/>FPS Doctor</h3><p>Datos locales de TP Client; sin inventar estadísticas ni subirlas a internet.</p></div><button disabled={watching||!!busy} onclick={() => void sample()}>Leer muestra</button></div>
      {#if report?.sample}<div class="metrics"><div><small>FPS reales</small><strong>{report.sample.fps.toFixed(0)}</strong></div><div><small>Tiempo de frame</small><strong>{report.sample.frame_time_ms?.toFixed(2)??'—'} ms</strong></div><div><small>Heap Java</small><strong>{report.sample.heap_used_mb.toFixed(0)} / {report.sample.heap_max_mb.toFixed(0)} MB</strong></div></div><p class="note">{report.samples} muestras · {report.sample.focused?'Juego con foco':'Sin foco'} · {report.sample.has_world?'Mundo activo':'Sin mundo'}</p>{/if}
      <p class="note">{report?.note??'Activa el informe local opcional en Rendimiento dentro de TP Client. El análisis ignora los primeros 45 segundos, el juego sin foco y los límites intencionales de 30 FPS o menos.'}</p>
      {#each report?.findings??[] as finding}<article class="finding"><h4>{finding.title}</h4><p>{finding.explanation}</p><strong>Próximo paso</strong><p>{finding.action}</p></article>{/each}
      <p class="note">Benchmark A/B: datos insuficientes. Una comparación válida requiere repetir mundo, ruta, resolución, versión, Java, mods y opciones. Las muestras del menú no son un benchmark.</p>
    </section>
    <section class="group"><div class="section-heading"><div><h3><UiIcon name="scan" size={19}/>Crash Doctor</h3><p>Busca indicios en los registros locales de la instancia elegida.</p></div><button disabled={!!busy} onclick={() => void inspect()}>Analizar registros</button></div>
      {#if diagnosis}<p class="note">{diagnosis.inspected} archivos inspeccionados · {diagnosis.source}</p>{#each diagnosis.findings as finding}<article class="finding"><h4>{finding.title}</h4><p>{finding.explanation}</p><strong>Próximo paso</strong><p>{finding.action}</p></article>{:else}<p class="notice">{diagnosis.inspected?'No se encontró un patrón de fallo reconocido. Esto no demuestra que el juego funcione correctamente.':'Esta instalación todavía no tiene registros legibles para analizar.'}</p>{/each}<p class="note">{diagnosis.note}</p>{/if}
    </section>
  {/if}
</section>
{#if confirmation}
  <dialog bind:this={dialog} oncancel={() => confirmation=null} aria-label="Confirmar ajuste gráfico" class="confirm"><h3>{confirmation==='restore'?'Restaurar configuración original':'Aplicar '+confirmation.name}</h3><p>{confirmation==='restore'?'Se restaurarán los bytes exactos de options.txt guardados antes del primer cambio. Si detectamos una edición manual posterior no se sobrescribirá.':confirmation.explanation}</p>{#if confirmation!=='restore'}<dl>{#each Object.entries(confirmation.changes) as [key,value]}<div><dt>{key}</dt><dd>{value}</dd></div>{/each}</dl><p>Se guardará una copia local verificada con SHA-256. No cambia mods, mundos, shaders ni memoria Java.</p>{/if}<div class="actions"><button onclick={() => confirmation=null}>Cancelar</button><button class="primary" onclick={() => void apply()}>Confirmar</button></div></dialog>
{/if}

<style>
  .performance-center{display:grid;gap:20px;color:var(--text-primary,#eee8f7)}header,.section-heading{display:flex;justify-content:space-between;align-items:center;gap:18px}header h2,h3{display:flex;align-items:center;gap:10px}h2{margin:8px 0;font-size:26px}h3,h4{margin:0 0 10px}p{line-height:1.6;margin:5px 0;color:var(--text-secondary,#ada5ba)}.eyebrow{font-size:10px;letter-spacing:.12em;color:var(--accent,#b06bfa)}button{display:inline-flex;align-items:center;justify-content:center;gap:7px;background:#211a2c;color:#eee7f7;border:1px solid #665175;border-radius:7px;padding:10px 14px;font:inherit;cursor:pointer}button:hover:not(:disabled){background:#392347}button:disabled{opacity:.45;cursor:not-allowed}.primary{background:#8438b8;border-color:#b16de5}.target{display:grid;gap:8px;font-weight:600}select{width:100%;padding:12px;background:#13111d;border:1px solid #4c405a;border-radius:7px;color:#f2edf8;font:inherit;color-scheme:dark}.hardware,.presets{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.hardware article,.presets article,.group{background:#100e17e8;border:1px solid #383041;border-radius:10px;padding:20px}.hardware article{display:grid;gap:8px}.hardware small,.hardware span,.note,small{font-size:12px;color:#afa6bd}.hardware strong{font-size:23px;color:#dcc6f5}.hardware :global(svg){color:#c194e8}.presets article{display:flex;flex-direction:column;align-items:flex-start;gap:8px;padding:17px}.presets p{flex:1;font-size:13px}.group{display:grid;gap:15px}.section-heading h3{margin-bottom:6px}.section-heading p{font-size:13px}.notice{padding:14px;border:1px solid #53445f;border-radius:7px;background:#251c32}.notice.error{background:#30171b;border-color:#88414d;color:#ffc1ca}.metrics{display:flex;gap:28px;flex-wrap:wrap}.metrics div{display:grid;gap:8px}.metrics strong{font-size:22px;color:#d6b6f1}.finding{padding:17px;background:#241a2e;border-left:3px solid #b16de5;border-radius:4px}.finding strong{font-size:12px}.finding p{font-size:13px}.finding h4{font-size:15px}details{font-size:12px}summary{cursor:pointer;padding:8px 0}dl{display:grid;gap:6px;margin:10px 0}dl>div{display:flex;justify-content:space-between;gap:24px}dt{color:#c0b6ca}dd{margin:0;color:#f3eafa}.confirm::backdrop{background:#08060bc9}.confirm{color:#eee8f7;max-width:530px;width:100%;padding:28px;background:#17111f;border:1px solid #9163ac;border-radius:12px;box-shadow:0 20px 90px #000}.confirm h3{font-size:20px}.actions{display:flex;justify-content:flex-end;gap:12px;margin-top:22px}.confirm p,.confirm dl{font-size:13px}.confirm dl{background:#0e0a14;padding:15px;border-radius:6px}@media(max-width:850px){.hardware,.presets{grid-template-columns:1fr}.section-heading,header{align-items:flex-start;flex-direction:column}.metrics{gap:18px}}
</style>
